_LAST_SYNC = 0.0


def log_stage(step_idx: int, code: str, stage_pct: int, msg: str, force: bool = False):
    global _LAST_SYNC
    stage_pct = max(0, min(100, int(stage_pct)))
    STAGE_STATUS[code] = f"{'DONE' if stage_pct == 100 else 'RUNNING'} ({stage_pct}%)"

    completed_weight = sum(w for i, (_, w) in enumerate(STAGE_WEIGHTS) if i < step_idx - 1)
    current_weight = STAGE_WEIGHTS[step_idx - 1][1] * (stage_pct / 100.0)
    overall_pct = int(round(completed_weight + current_weight))

    ts = datetime.now().strftime("%H:%M:%S")
    line = f"[{ts}] TAHAP [{step_idx}/6] {code} ({stage_pct}% | Total: {overall_pct}%): {msg}"
    print(line, flush=True)

    now = time.time()
    if force or stage_pct in (0, 100) or (now - _LAST_SYNC >= 15):
        _LAST_SYNC = now
        try:
            rincian = "\n".join(
                f"  - [{i+1}/6] {name}: {STAGE_STATUS[name]}"
                for i, (name, _) in enumerate(STAGE_WEIGHTS)
            )
            with open(STATUS_FILE, "w", encoding="utf-8") as f:
                f.write(
                    f"STATUS: {'COMPLETED' if (step_idx == 6 and stage_pct == 100) else 'RUNNING'}\n"
                    f"JOB: {JOB_SLUG}\n"
                    f"OVERALL: {overall_pct}%\n"
                    f"CURRENT: {line}\n"
                    f"RINCIAN_TAHAP:\n{rincian}\n"
                )
        except Exception:
            pass


def ffprobe_duration(path: str) -> float:
    out = subprocess.check_output(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            path,
        ],
        text=True,
    ).strip()
    return float(out)


def generate_warm_pad_bgm(out_wav: str, duration_sec: float, sr: int = 48000):
    """Generate offline-safe historical warm ambient pad (Dm9 - Bbmaj7 - Gm7 - A7sus4)."""
    total_samples = int(math.ceil(duration_sec * sr))
    chords = [
        [146.83, 174.61, 220.00, 261.63, 329.63],  # Dm9
        [116.54, 174.61, 220.00, 293.66],          # Bbmaj7
        [98.00, 146.83, 174.61, 233.08],           # Gm7
        [110.00, 164.81, 220.00, 293.66],          # A7sus4
    ]
    chord_len = 4.0
    two_pi = 2.0 * math.pi

    with wave.open(out_wav, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)

        chunk_size = 48000
        for start in range(0, total_samples, chunk_size):
            end = min(total_samples, start + chunk_size)
            buf = bytearray()
            for n in range(start, end):
                t = n / sr
                idx = int(t / chord_len) % len(chords)
                local_t = t % chord_len
                env = math.sin(math.pi * min(1.0, local_t / chord_len)) ** 0.45
                freqs = chords[idx]
                val = 0.0
                for fi, f in enumerate(freqs):
                    detune = 1.0 + (0.0018 if fi % 2 == 0 else -0.0018)
                    val += math.sin(two_pi * f * detune * t)
                val = (val / len(freqs)) * env * 0.28
                sample = max(-32767, min(32767, int(val * 32767)))
                buf.extend(struct.pack("<h", sample))
            wf.writeframes(buf)


def generate_sfx_pack(sfx_dir: str, sr: int = 48000):
    """Generate 5 offline procedural WAV SFX files (48kHz mono pcm_s16le)."""
    os.makedirs(sfx_dir, exist_ok=True)
    two_pi = 2.0 * math.pi

    def write_samples(filename: str, samples):
        with wave.open(os.path.join(sfx_dir, filename), "wb") as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sr)
            buf = bytearray()
            for s in samples:
                clamped = max(-32767, min(32767, int(s * 32767)))
                buf.extend(struct.pack("<h", clamped))
            wf.writeframes(buf)

    # 1. whoosh.wav (0.40s filtered sweep)
    n_whoosh = int(0.40 * sr)
    seed = 1234567
    lp = 0.0
    whoosh_samples = []
    for i in range(n_whoosh):
        t = i / sr
        seed = (1103515245 * seed + 12345) & 0x7FFFFFFF
        noise = (seed / 0x7FFFFFFF) * 2.0 - 1.0
        alpha = 0.04 + 0.14 * math.sin(math.pi * (t / 0.40))
        lp = lp + alpha * (noise - lp)
        env = math.sin(math.pi * (t / 0.40)) ** 1.4
        whoosh_samples.append(lp * env * 0.45)
    write_samples("whoosh.wav", whoosh_samples)

    # 2. pop.wav (0.18s warm drop-pitch impulse)
    n_pop = int(0.18 * sr)
    pop_samples = []
    phase = 0.0
    for i in range(n_pop):
        t = i / sr
        freq = 540.0 * math.exp(-t * 16.0) + 140.0
        phase += two_pi * freq / sr
        env = math.exp(-t * 24.0) * min(1.0, t / 0.006)
        pop_samples.append(math.sin(phase) * env * 0.42)
    write_samples("pop.wav", pop_samples)

    # 3. tick.wav (0.12s crisp parchment tick)
    n_tick = int(0.12 * sr)
    tick_samples = [
        math.sin(two_pi * 1150.0 * (i / sr)) * math.exp(-(i / sr) * 45.0) * 0.35
        for i in range(n_tick)
    ]
    write_samples("tick.wav", tick_samples)

    # 4. chime.wav (0.32s warm harmonic bell)
    n_chime = int(0.32 * sr)
    chime_samples = []
    for i in range(n_chime):
        t = i / sr
        env = math.exp(-t * 9.5) * min(1.0, t / 0.01)
        sig = (
            0.55 * math.sin(two_pi * 587.33 * t)
            + 0.30 * math.sin(two_pi * 880.00 * t)
            + 0.15 * math.sin(two_pi * 1174.66 * t)
        )
        chime_samples.append(sig * env * 0.40)
    write_samples("chime.wav", chime_samples)

    # 5. thud.wav (0.24s soft sub-bass impact)
    n_thud = int(0.24 * sr)
    thud_samples = []
    phase = 0.0
    for i in range(n_thud):
        t = i / sr
        freq = 98.0 * math.exp(-t * 8.0) + 42.0
        phase += two_pi * freq / sr
        env = math.exp(-t * 14.0) * min(1.0, t / 0.008)
        thud_samples.append(math.sin(phase) * env * 0.48)
    write_samples("thud.wav", thud_samples)


async def synthesize_segments(work_dir: str):
    import edge_tts

    audio_tmp = os.path.join(work_dir, "audio_tmp")
    os.makedirs(audio_tmp, exist_ok=True)

    async def synth_one(idx: int, seg: dict):
        raw_mp3 = os.path.join(audio_tmp, f"seg_{idx}.mp3")
        clean_wav = os.path.join(audio_tmp, f"seg_{idx}.wav")
        comm = edge_tts.Communicate(seg["text"], VOICE, rate=RATE, pitch=PITCH, boundary="WordBoundary")
        boundaries = []
        with open(raw_mp3, "wb") as f:
            async for chunk in comm.stream():
                if chunk["type"] == "audio":
                    f.write(chunk["data"])
                elif chunk["type"] == "WordBoundary":
                    boundaries.append({
                        "word": chunk["text"],
                        "offset_sec": chunk["offset"] / 10_000_000.0,
                        "dur_sec": chunk["duration"] / 10_000_000.0,
                    })
        subprocess.run(
            ["ffmpeg", "-y", "-i", raw_mp3, "-ar", "48000", "-ac", "1", "-c:a", "pcm_s16le", clean_wav],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
        )
        dur = ffprobe_duration(clean_wav)
        log_stage(2, "AUDIO", int(((idx + 1) / len(SEGMENTS)) * 70), f"VO Segmen {idx+1}/{len(SEGMENTS)} selesai ({dur:.2f} dtk)")
        return idx, clean_wav, dur, boundaries

    results = await asyncio.gather(*(synth_one(i, s) for i, s in enumerate(SEGMENTS)))
    results.sort(key=lambda x: x[0])

    gap_wav = os.path.join(audio_tmp, "gap.wav")
    gap_sec = 0.24
    subprocess.run(
        ["ffmpeg", "-y", "-f", "lavfi", "-i", "anullsrc=r=48000:cl=mono", "-t", str(gap_sec), "-c:a", "pcm_s16le", gap_wav],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
    )

    concat_list = os.path.join(audio_tmp, "concat.txt")
    scenes = []
    words = []
    sfx_events = []
    cur_sec = 0.0

    with open(concat_list, "w", encoding="utf-8") as cf:
        for i, (_, wav_path, dur, bounds) in enumerate(results):
            seg_id = SEGMENTS[i]["id"]
            start_frame = int(round(cur_sec * FPS))
            seg_total_sec = dur + (gap_sec if i < len(results) - 1 else 0.35)
            dur_frames = max(36, int(round(seg_total_sec * FPS)))

            scenes.append({
                "id": seg_id,
                "startFrame": start_frame,
                "durationInFrames": dur_frames,
            })

            if i > 0:
                sfx_events.append({"type": "whoosh", "frame": max(0, start_frame - 9), "volume": 0.15})

            if seg_id == "SCN-01":
                sfx_events.append({"type": "thud", "frame": start_frame + 4, "volume": 0.19})
                sfx_events.append({"type": "pop", "frame": start_frame + 18, "volume": 0.17})
            elif seg_id == "SCN-02":
                sfx_events.append({"type": "thud", "frame": start_frame + 10, "volume": 0.18})
                sfx_events.append({"type": "chime", "frame": start_frame + 152, "volume": 0.16})
                sfx_events.append({"type": "pop", "frame": start_frame + 168, "volume": 0.17})
            elif seg_id == "SCN-03":
                sfx_events.append({"type": "tick", "frame": start_frame + 28, "volume": 0.14})
                sfx_events.append({"type": "tick", "frame": start_frame + 58, "volume": 0.14})
                sfx_events.append({"type": "pop", "frame": start_frame + 132, "volume": 0.17})
            elif seg_id == "SCN-04":
                sfx_events.append({"type": "chime", "frame": start_frame + 52, "volume": 0.17})
                sfx_events.append({"type": "pop", "frame": start_frame + 122, "volume": 0.16})
            elif seg_id == "SCN-05":
                sfx_events.append({"type": "thud", "frame": start_frame + 12, "volume": 0.18})
                sfx_events.append({"type": "chime", "frame": start_frame + 58, "volume": 0.17})

            for b in bounds:
                w_txt = b["word"].strip()
                if not w_txt:
                    continue
                sf = int(round((cur_sec + b["offset_sec"]) * FPS))
                ef = max(sf + 2, int(round((cur_sec + b["offset_sec"] + b["dur_sec"]) * FPS)))
                if words and sf <= words[-1]["startFrame"]:
                    sf = words[-1]["startFrame"] + 1
                    ef = max(sf + 2, ef)
                words.append({"word": w_txt, "startFrame": sf, "endFrame": ef})

            cf.write(f"file '{wav_path}'\n")
            if i < len(results) - 1:
                cf.write(f"file '{gap_wav}'\n")
            cur_sec += seg_total_sec

    public_dir = os.path.join(work_dir, "public")
    os.makedirs(public_dir, exist_ok=True)
    vo_out = os.path.join(public_dir, "vo.wav")
    subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", concat_list, "-c", "copy", vo_out],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=True,
    )
    total_dur = ffprobe_duration(vo_out)
    total_frames = int(math.ceil(total_dur * FPS))

    # Fallback forced alignment with faster-whisper if WordBoundary returned empty
    if not words:
        log_stage(2, "AUDIO", 80, "Menjalankan word alignment faster-whisper...")
        from faster_whisper import WhisperModel
        wm = WhisperModel("base", device="cpu", compute_type="int8")
        segs_iter, _ = wm.transcribe(vo_out, language="id", word_timestamps=True)
        for s in segs_iter:
            for w in (s.words or []):
                wt = w.word.strip()
                if not wt:
                    continue
                sf = int(round(w.start * FPS))
                ef = max(sf + 2, int(round(w.end * FPS)))
                if words and sf <= words[-1]["startFrame"]:
                    sf = words[-1]["startFrame"] + 1
                    ef = max(sf + 2, ef)
                words.append({"word": wt, "startFrame": sf, "endFrame": ef})

    # Align last scene end cleanly to total_frames
    if scenes:
        scenes[-1]["durationInFrames"] = max(36, total_frames - scenes[-1]["startFrame"])

    log_stage(2, "AUDIO", 88, "Membentuk musik latar ambient & efek suara lokal...")
    generate_warm_pad_bgm(os.path.join(public_dir, "bgm.wav"), total_dur + 0.5)
    generate_sfx_pack(os.path.join(public_dir, "sfx"))

    manifest = {
        "fps": FPS,
        "totalFrames": total_frames,
        "bgmMood": "warm-pad",
        "scenes": scenes,
        "words": words,
        "sfxEvents": sfx_events,
    }
    with open(os.path.join(public_dir, "manifest.json"), "w", encoding="utf-8") as mf:
        json.dump(manifest, mf, ensure_ascii=False, indent=2)

    log_stage(2, "AUDIO", 100, f"Audio & manifest siap ({total_dur:.2f} dtk, {total_frames} frame, {len(words)} kata)", force=True)
    return total_frames, total_dur


def run_streaming_cmd(cmd, cwd, env, on_line):
    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=1,
        text=True,
        errors="replace",
    )
    buf = ""
    last_lines = []
    assert proc.stdout is not None
    while True:
        ch = proc.stdout.read(1)
        if not ch and proc.poll() is not None:
            break
        if ch in ("\r", "\n"):
            line = buf.strip()
            buf = ""
            if line:
                last_lines.append(line)
                if len(last_lines) > 40:
                    last_lines.pop(0)
                on_line(line)
        else:
            buf += ch
    rc = proc.wait()
    return rc, last_lines


def main():
    job_id = datetime.now().strftime("job_%Y%m%d_%H%M%S")
    work_root = "/content/work" if os.path.isdir("/content") else "/tmp/remotion_work"
    os.makedirs(work_root, exist_ok=True)

    # Clean stale orphan work dirs
    for entry in os.listdir(work_root):
        old_p = os.path.join(work_root, entry)
        if os.path.isdir(old_p):
            shutil.rmtree(old_p, ignore_errors=True)

    work_dir = os.path.join(work_root, job_id)
    os.makedirs(work_dir, exist_ok=True)

    try:
        # [1/6] SETUP
        log_stage(1, "SETUP", 10, "Menyiapkan direktori kerja & cache idempoten...", force=True)
        py_site = os.path.join(CACHE_DIR, "py_site")
        npm_cache = os.path.join(CACHE_DIR, "npm")
        node_tpl = os.path.join(CACHE_DIR, "node_template")
        hf_cache = os.path.join(CACHE_DIR, "hf")
        chrom_cache = os.path.join(CACHE_DIR, "chromium")
        for d in (py_site, npm_cache, node_tpl, hf_cache, chrom_cache):
            os.makedirs(d, exist_ok=True)

        if py_site not in sys.path:
            sys.path.insert(0, py_site)
        os.environ["PYTHONPATH"] = f"{py_site}:{os.environ.get('PYTHONPATH', '')}"
        os.environ["NPM_CONFIG_CACHE"] = npm_cache
        os.environ["HF_HOME"] = hf_cache

        log_stage(1, "SETUP", 45, "Memeriksa dependensi Python (edge-tts, faster-whisper)...")
        try:
            import edge_tts  # noqa: F401
            import faster_whisper  # noqa: F401
        except ImportError:
            subprocess.run(
                [sys.executable, "-m", "pip", "install", "-q", "--no-warn-script-location", "--target", py_site, "edge-tts", "faster-whisper"],
                check=True,
            )

        log_stage(1, "SETUP", 75, "Memeriksa FFmpeg & Node.js runtime...")
        if not shutil.which("ffmpeg"):
            subprocess.run(["sudo", "apt-get", "update", "-qq"], check=False)
            subprocess.run(["sudo", "apt-get", "install", "-y", "-qq", "ffmpeg", "fonts-dejavu-core", "fonts-liberation"], check=False)

        log_stage(1, "SETUP", 100, "Lingkungan runtime siap (zero-reinstall verified)", force=True)

        # [2/6] AUDIO
        log_stage(2, "AUDIO", 5, "Memulai sintesis narasi VO id-ID-ArdiNeural...", force=True)
        total_frames, total_dur = asyncio.run(synthesize_segments(work_dir))

        # [3/6] PROJECT
        log_stage(3, "PROJECT", 10, "Mendekode kode proyek Remotion 4.x...", force=True)
        for rel_path, b64_str in PROJECT_FILES_B64.items():
            full_path = os.path.join(work_dir, rel_path)
            os.makedirs(os.path.dirname(full_path), exist_ok=True)
            with open(full_path, "wb") as wf:
                wf.write(base64.b64decode(b64_str))

        pkg_hash = hashlib.sha256(open(os.path.join(work_dir, "package.json"), "rb").read()).hexdigest()
        hash_file = os.path.join(node_tpl, "pkg.hash")
        nm_tar = os.path.join(node_tpl, "node_modules.tar")

        if os.path.exists(hash_file) and open(hash_file).read().strip() == pkg_hash and os.path.exists(nm_tar):
            log_stage(3, "PROJECT", 50, "Mengekstrak cache node_modules.tar ke disk lokal...")
            subprocess.run(["tar", "-xf", nm_tar, "-C", work_dir], check=True)
            bin_dir = os.path.join(work_dir, "node_modules", ".bin")
            if os.path.isdir(bin_dir):
                subprocess.run(["chmod", "-R", "+x", bin_dir], check=False)
        else:
            log_stage(3, "PROJECT", 40, "Memasang paket npm Remotion 4.0.220...")
            subprocess.run(["npm", "install", "--no-audit", "--no-fund", "--prefer-offline"], cwd=work_dir, check=True)
            subprocess.run(["tar", "-cf", nm_tar, "-C", work_dir, "node_modules"], check=False)
            with open(hash_file, "w") as hf:
                hf.write(pkg_hash)

        chrom_dir = "/tmp/remotion-chromium"
        os.makedirs(chrom_dir, exist_ok=True)
        chrom_tar = os.path.join(chrom_cache, "chromium.tar")
        env = os.environ.copy()
        env["PUPPETEER_CACHE_DIR"] = chrom_dir
        env["PLAYWRIGHT_BROWSERS_PATH"] = chrom_dir
        env["NODE_OPTIONS"] = "--max-old-space-size=4096"

        if os.path.exists(chrom_tar):
            log_stage(3, "PROJECT", 80, "Menghidrasi cache Chromium headless...")
            subprocess.run(["tar", "-xf", chrom_tar, "-C", chrom_dir], check=True)
            subprocess.run(["chmod", "-R", "+x", chrom_dir], check=False)
        else:
            log_stage(3, "PROJECT", 75, "Menyiapkan browser Chromium Remotion...")
            subprocess.run(["npx", "remotion", "browser", "ensure"], cwd=work_dir, env=env, check=True)
            subprocess.run(["tar", "-cf", chrom_tar, "-C", chrom_dir, "."], check=False)

        subprocess.run(["npx", "remotion", "compositions", "src/index.ts"], cwd=work_dir, env=env, check=True)
        log_stage(3, "PROJECT", 100, "Proyek & komposisi MainComp terverifikasi", force=True)

        # [4/6] RENDER
        concurrency = max(2, min(4, os.cpu_count() or 2))
        raw_mp4 = os.path.join(work_dir, "raw_out.mp4")
        log_stage(4, "RENDER", 2, f"Merender {total_frames} frame (1080x1920 @ {FPS}fps, concurrency={concurrency})...", force=True)

        render_t0 = time.time()
        last_pct_logged = -5

        def on_render_line(line: str):
            nonlocal last_pct_logged
            m = re.search(r"(\d+)\s*/\s*(\d+)", line)
            if m:
                cur_f = int(m.group(1))
                tot_f = max(1, int(m.group(2)))
                if tot_f >= 100 and cur_f <= tot_f:
                    pct = 5 + int((cur_f / tot_f) * 90)
                    if pct >= last_pct_logged + 5:
                        last_pct_logged = pct
                        elapsed = max(0.1, time.time() - render_t0)
                        fps_rate = cur_f / elapsed
                        eta = int((tot_f - cur_f) / max(0.1, fps_rate))
                        log_stage(4, "RENDER", pct, f"Frame {cur_f}/{tot_f} ({fps_rate:.1f} fps | ETA ~{eta} dtk)")

        primary_cmd = [
            "npx", "remotion", "render", "src/index.ts", "MainComp", raw_mp4,
            "--codec=h264", "--x264-preset=ultrafast", "--crf=18",
            "--jpeg-quality=72", "--pixel-format=yuv420p",
            f"--concurrency={concurrency}", "--gl=swangle", "--log=verbose",
        ]
        rc, tail = run_streaming_cmd(primary_cmd, work_dir, env, on_render_line)
        if rc != 0 or not os.path.exists(raw_mp4):
            log_stage(4, "RENDER", 50, "Menjalankan fallback renderer single-worker...")
            fallback_cmd = [
                "npx", "remotion", "render", "src/index.ts", "MainComp", raw_mp4,
                "--codec=h264", "--x264-preset=ultrafast", "--crf=18",
                "--jpeg-quality=70", "--pixel-format=yuv420p",
                "--concurrency=1", "--gl=angle", "--use-angle=swiftshader", "--log=verbose",
            ]
            rc2, tail2 = run_streaming_cmd(fallback_cmd, work_dir, env, on_render_line)
            if rc2 != 0 or not os.path.exists(raw_mp4):
                raise RuntimeError("Render Remotion gagal:\n" + "\n".join(tail2[-20:]))

        log_stage(4, "RENDER", 100, "Render mentah Remotion selesai", force=True)

        # [5/6] COMPRESS
        final_tmp = os.path.join(work_dir, "final_out.mp4")
        log_stage(5, "COMPRESS", 5, "Mengompresi H.264 & mastering audio -14 LUFS...", force=True)
        total_us = max(1, int(total_dur * 1_000_000))

        def on_ffmpeg_line(line: str):
            if line.startswith("out_time_us="):
                try:
                    us = int(line.split("=", 1)[1].strip())
                    pct = min(99, int((us / total_us) * 100))
                    log_stage(5, "COMPRESS", pct, f"Encoding H.264 + AAC ({pct}%)")
                except ValueError:
                    pass

        ff_cmd = [
            "ffmpeg", "-y", "-i", raw_mp4,
            "-c:v", "libx264", "-preset", "veryfast", "-crf", "21",
            "-maxrate", "6M", "-bufsize", "12M",
            "-profile:v", "high", "-level", "4.1", "-pix_fmt", "yuv420p",
            "-af", "loudnorm=I=-14:TP=-1.5:LRA=11",
            "-c:a", "aac", "-b:a", "128k", "-ar", "48000",
            "-movflags", "+faststart",
            "-progress", "pipe:1", "-nostats",
            final_tmp,
        ]
        ff_rc, ff_tail = run_streaming_cmd(ff_cmd, work_dir, env, on_ffmpeg_line)
        if ff_rc != 0 or not os.path.exists(final_tmp):
            raise RuntimeError("Kompresi FFmpeg gagal:\n" + "\n".join(ff_tail[-15:]))
        log_stage(5, "COMPRESS", 100, "Kompresi & mastering selesai", force=True)

        # [6/6] QC_PROMOTE
        log_stage(6, "QC_PROMOTE", 30, "Memvalidasi kualitas MP4 via ffprobe...", force=True)
        size_bytes = os.path.getsize(final_tmp)
        if size_bytes < 100_000:
            raise RuntimeError(f"Ukuran file terlalu kecil ({size_bytes} bytes)")
        final_dur = ffprobe_duration(final_tmp)

        log_stage(6, "QC_PROMOTE", 65, "Mengekstrak sampul otomatis cover.png...")
        cover_tmp = os.path.join(work_dir, "cover_out.png")
        ss_hook = min(1.2, max(0.3, final_dur * 0.08))
        subprocess.run(
            ["ffmpeg", "-y", "-ss", f"{ss_hook:.2f}", "-i", final_tmp, "-vframes", "1", "-q:v", "2", cover_tmp],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
        )

        out_mp4 = os.path.join(PROJECTS_DIR, f"{JOB_SLUG}_final.mp4")
        out_cover = os.path.join(PROJECTS_DIR, f"{JOB_SLUG}_cover.png")
        out_report = os.path.join(PROJECTS_DIR, f"{JOB_SLUG}_render_report.json")

        shutil.copy2(final_tmp, out_mp4)
        shutil.copy2(cover_tmp, out_cover)

        report = {
            "job": JOB_SLUG,
            "status": "COMPLETED",
            "duration_sec": round(final_dur, 2),
            "size_mb": round(size_bytes / (1024 * 1024), 2),
            "resolution": "1080x1920",
            "fps": FPS,
            "mp4_path": out_mp4,
            "cover_path": out_cover,
            "timestamp": datetime.now().isoformat(),
        }
        with open(out_report, "w", encoding="utf-8") as rf:
            json.dump(report, rf, indent=2)

        if STUDIO_DIR != REPO_ROOT:
            drive_proj = os.path.join(STUDIO_DIR, "projects")
            os.makedirs(drive_proj, exist_ok=True)
            shutil.copy2(out_mp4, os.path.join(drive_proj, os.path.basename(out_mp4)))
            shutil.copy2(out_cover, os.path.join(drive_proj, os.path.basename(out_cover)))
            shutil.copy2(out_report, os.path.join(drive_proj, os.path.basename(out_report)))

        log_stage(
            6,
            "QC_PROMOTE",
            100,
            f"SELESAI! MP4 ({report['size_mb']} MB, {report['duration_sec']} dtk) & Cover PNG siap di {PROJECTS_DIR}",
            force=True,
        )
    except Exception as exc:
        err_path = os.path.join(PROJECTS_DIR, "error_log.txt")
        with open(err_path, "w", encoding="utf-8") as ef:
            ef.write(f"[{datetime.now().isoformat()}] FAILED: {exc}\n")
        raise
    finally:
        shutil.rmtree(work_dir, ignore_errors=True)


if __name__ == "__main__":
    main()
